const digitsE=s=>String(s||'').replace(/\D/g,'');
function ebookForWorkE(w){
  for(const e of (ED[w.slug]||[])){
    const hit=EBOOK_BY_PRINT_ISBN[digitsE(e.isbn||e.ean)];
    if(hit)return hit;
  }
  return null;
}
function physicalLabelE(e){
  const hay=[e?.label,e?.format,e?.binding].filter(Boolean).join(' ').toLowerCase();
  if(hay.includes('box'))return 'Box';
  if(hay.includes('capa dura')||hay.includes('capa-dura')||hay.includes('hardcover'))return 'Capa dura';
  return 'Brochura';
}
function ebookStoreUrlE(name,w,d){
  const q=encodeURIComponent([w.title,authorNames(w)].filter(Boolean).join(' '));
  if(name==='Amazon'&&d.asin)return 'https://www.amazon.com.br/dp/'+encodeURIComponent(d.asin);
  if(name==='Apple Books'&&d.apple)return 'https://books.apple.com/br/book/id'+encodeURIComponent(d.apple);
  if(name==='Kobo')return 'https://www.kobo.com/br/pt/search?query='+q;
  if(name==='Google Play Livros')return 'https://play.google.com/store/search?q='+q+'&c=books';
  return 'https://www.amazon.com.br/s?k='+q+'&i=digital-text';
}
function ebookPriceTextE(d){return d.price||'Preço na loja'}
const baseBookPageE=bookPage;
bookPage=function(slug,params){
  const w=W[slug]; if(!w)return notFound();
  const digital=ebookForWorkE(w);
  const ebookMode=!!digital&&params.get('formato')==='ebook';
  let html=baseBookPageE(slug,params);
  const doc=new DOMParser().parseFromString(html,'text/html');
  const main=doc.querySelector('main'); if(!main)return html;
  const editionLabel=main.querySelector('.edition-label');
  if(editionLabel)editionLabel.textContent='ESCOLHA O FORMATO';
  main.querySelectorAll('.editions .ed').forEach(btn=>{
    const first=[...btn.childNodes].find(n=>n.nodeType===Node.TEXT_NODE);
    if(first){
      const txt=first.textContent.trim();
      if(/edição impressa|edicao impressa|impresso/i.test(txt))first.textContent='Brochura';
    }
  });
  main.querySelectorAll('.meta-row').forEach(row=>{
    const k=row.querySelector('span')?.textContent.trim().toLowerCase();
    const val=row.querySelector('strong');
    if(k==='formato'&&val&&/impresso|edição impressa|edicao impressa/i.test(val.textContent))val.textContent='Brochura';
    if(k==='acabamento'&&val&&/impresso|edição impressa|edicao impressa/i.test(val.textContent))val.textContent='Brochura';
  });
  if(!digital)return main.outerHTML;
  const eds=main.querySelector('.editions');
  if(eds){
    const b=doc.createElement('button');
    b.className='ed ebook-ed'+(ebookMode?' active':'');
    b.setAttribute('onclick',"go('/livros/"+slug+"?formato=ebook')");
    b.innerHTML='E-book<small>'+esc(ebookPriceTextE(digital))+'</small>';
    eds.appendChild(b);
  }
  if(!ebookMode)return main.outerHTML;
  main.querySelectorAll('.editions .ed:not(.ebook-ed)').forEach(b=>b.classList.remove('active'));
  const price=main.querySelector('.price');
  if(price)price.innerHTML='<span style="display:block;font:700 9px/1.2 \'Archivo\',Arial,sans-serif;letter-spacing:.14em;text-transform:uppercase;color:#7c736b;margin-bottom:5px">Versão digital</span>'+esc(ebookPriceTextE(digital));
  const retailTitle=main.querySelector('.retail-title');
  if(retailTitle)retailTitle.textContent='ONDE COMPRAR O E-BOOK';
  const retailGrid=main.querySelector('.retail-grid');
  if(retailGrid){
    retailGrid.innerHTML=['Amazon','Kobo','Google Play Livros','Apple Books'].map(n=>'<div class="retail" onclick="window.open(\''+esc(ebookStoreUrlE(n,w,digital))+'\',\'_blank\')">'+esc(n)+' <span>↗</span></div>').join('');
  }
  const meta=main.querySelector('.meta-grid');
  if(meta)meta.innerHTML='<div><div class="meta-row"><span>Formato</span><strong>E-book</strong></div><div class="meta-row"><span>Arquivo</span><strong>EPUB</strong></div></div><div><div class="meta-row"><span>ISBN digital</span><strong>'+esc(digital.eisbn||'—')+'</strong></div><div class="meta-row"><span>Tipo</span><strong>Digital</strong></div></div>';
  return main.outerHTML;
};
